INSERT IGNORE INTO cms_site_module_revisions(module_key,revision,snapshot,action) SELECT b.module_key,b.revision,JSON_OBJECT('draft',JSON_EXTRACT(b.draft,'$'),'published',JSON_EXTRACT(b.published,'$')),'before-copy-review' FROM kemsor_copy_modules_before b JOIN cms_site_modules m ON m.module_key=b.module_key WHERE NOT(m.draft<=>b.draft) OR NOT(m.published<=>b.published);
INSERT INTO cms_site_module_revisions(module_key,revision,snapshot,action) SELECT m.module_key,m.revision+1,JSON_OBJECT('draft',JSON_EXTRACT(m.draft,'$'),'published',JSON_EXTRACT(m.published,'$')),'copy-review' FROM cms_site_modules m JOIN kemsor_copy_modules_before b ON m.module_key=b.module_key WHERE NOT(m.draft<=>b.draft) OR NOT(m.published<=>b.published);
UPDATE cms_site_modules m JOIN kemsor_copy_modules_before b ON m.module_key=b.module_key SET m.revision=m.revision+1,m.updated_by=NULL WHERE NOT(m.draft<=>b.draft) OR NOT(m.published<=>b.published);
INSERT IGNORE INTO cms_managed_revisions(content_id,revision,snapshot,action) SELECT b.id,b.revision,JSON_OBJECT('draft',JSON_EXTRACT(b.draft,'$'),'published',JSON_EXTRACT(b.published,'$')),'before-copy-review' FROM kemsor_copy_hero_before b JOIN cms_managed_content m ON m.id=b.id WHERE NOT(m.draft<=>b.draft) OR NOT(m.published<=>b.published);
INSERT INTO cms_managed_revisions(content_id,revision,snapshot,action) SELECT m.id,m.revision+1,JSON_OBJECT('draft',JSON_EXTRACT(m.draft,'$'),'published',JSON_EXTRACT(m.published,'$')),'copy-review' FROM cms_managed_content m JOIN kemsor_copy_hero_before b ON m.id=b.id WHERE NOT(m.draft<=>b.draft) OR NOT(m.published<=>b.published);
UPDATE cms_managed_content m JOIN kemsor_copy_hero_before b ON m.id=b.id SET m.revision=m.revision+1,m.updated_by=NULL WHERE NOT(m.draft<=>b.draft) OR NOT(m.published<=>b.published);
INSERT INTO cms_audit(action,target_type,target_id) VALUES('copy_review','website','025_editorial_copy_review');
DROP TEMPORARY TABLE kemsor_copy_modules_before;
DROP TEMPORARY TABLE kemsor_copy_hero_before;
